-- See https://wiki.hypr.land/Configuring/Basics/Monitors/
-- Keep this generic rule as a fallback for displays not present in the
-- configuration generated by nwg-displays.
hl.monitor({
    output   = "",
    mode     = "preferred",
    position = "auto",
    scale    = "auto",
})

-- nwg-displays regenerates this file and reloads Hyprland when settings are applied.
-- También lo genera otra herramienta (nwg-displays), así que va con pcall por
-- el mismo motivo que 'noctalia': que falte no puede abortar la config.
if not pcall(require, "monitors") then
  print("[hyprland] no encontré monitors.lua; revisá ~/.config/hypr/monitors.conf")
end


