-- Refer to https://wiki.hypr.land/Configuring/Basics/Variables/
-- NOTA: no se tocaron colores, bordes ni blur — se dejaron exactamente como estaban.
hl.config({
    general = {
        gaps_in  = 4,
        gaps_out = 10,

        border_size = 2,

        col = {
            active_border   = { colors = {"rgba(33ccffee)", "rgba(00ff99ee)"}, angle = 45 },
            inactive_border = "rgba(595959aa)",
        },

        -- Set to true to enable resizing windows by clicking and dragging on borders and gaps
        resize_on_border = false,

        -- Please see https://wiki.hypr.land/Configuring/Advanced-and-Cool/Tearing/ before you turn this on
        allow_tearing = false,

        layout = "dwindle",
    },

    decoration = {
        -- Rounding más generoso: las esquinas "burbuja" son una de las señas
        -- de identidad del look Aero/glass (nada de esquinas casi rectas).
        rounding       = 16,
        rounding_power = 2.4,

        -- Se mantienen los valores de opacidad que ya tenías.
        active_opacity   = 0.9,
        inactive_opacity = 0.8,

        -- Sombra un poco más suave y difusa: en vez de una sombra "dura"
        -- de tema oscuro moderno, buscamos el halo suave típico de Aero.
        shadow = {
            enabled      = true,
            range        = 18,
            render_power = 3,
            color        = 0xee1a1a1a,
        },

        -- Blur más pesado y con más "passes": es lo que hace el trabajo
        -- pesado del efecto vidrio esmerilado. contrast/brightness altos
        -- imitan el brillo sobre-expuesto típico del glass de Vista/7;
        -- noise le da grano fino para que no se vea un blur plano.
        blur = {
            enabled            = true,
            size               = 8,
            passes             = 4,
            vibrancy           = 0.1696,
            contrast           = 1.2,
            brightness         = 1.15,
            noise              = 0.02,
            new_optimizations  = true,
            xray               = true,
            ignore_opacity     = true,
            popups             = true, -- menús/tooltips también con vidrio
        },
    },

    animations = {
        enabled = true,
    },
})

-- ==========================================================================
--  ANIMACIONES — ESTILO "PUNK-AERO"
--  Golpes rápidos con overshoot y resortes elásticos para una sensación viva.
--  Nada de esto toca colores, bordes ni blur: es pura coreografía de movimiento.
-- ==========================================================================

-- Curvas Bezier "punk": entrada agresiva con overshoot (rebasa y vuelve).
hl.curve("punkSnap",     { type = "bezier", points = { {0.83, 0}, {0.17, 1.15} } }) -- golpe seco con rebote
hl.curve("punkKick",     { type = "bezier", points = { {0.9, -0.35}, {0.1, 1.5} } }) -- patada: anticipación + overshoot fuerte
hl.curve("punkSlam",     { type = "bezier", points = { {0.95, 0.05}, {0.05, 0.95} } }) -- cierre tipo portazo, casi instantáneo
hl.curve("aeroSwing",    { type = "bezier", points = { {0.36, 1.4}, {0.64, -0.4} } })

-- Resortes elásticos con más oscilación
-- que el resorte por defecto (más stiffness = más rápido, menos dampening = más rebote).
hl.curve("aeroSpring",    { type = "spring", mass = 0.65, stiffness = 260, dampening = 14 })
hl.curve("punkSpring",    { type = "spring", mass = 0.65,  stiffness = 340, dampening = 11 })

-- Curvas base originales, se mantienen por si algo las referencia.
hl.curve("easeOutQuint",   { type = "bezier", points = { {0.23, 1},    {0.32, 1}    } })
hl.curve("easeInOutCubic", { type = "bezier", points = { {0.65, 0.05}, {0.36, 1}    } })
hl.curve("linear",         { type = "bezier", points = { {0, 0},       {1, 1}       } })
hl.curve("almostLinear",   { type = "bezier", points = { {0.5, 0.5},   {0.75, 1}    } })
hl.curve("quick",          { type = "bezier", points = { {0.15, 0},    {0.1, 1}     } })
hl.curve("easy",           { type = "spring", mass = 1, stiffness = 238.1191, dampening = 24.21279333 })

-- Velocidades altas con resortes elásticos.
hl.animation({ leaf = "global",        enabled = true,  speed = 10,   bezier = "default" })
hl.animation({ leaf = "border",        enabled = true,  speed = 9,    bezier = "punkSnap" })
hl.animation({ leaf = "windows",       enabled = true,  speed = 7.5,  spring = "aeroSpring" })
hl.animation({ leaf = "windowsIn",     enabled = true,  speed = 7,    spring = "punkSpring",    style = "popin 70%" })
hl.animation({ leaf = "windowsOut",    enabled = true,  speed = 3.2,  bezier = "punkSlam",       style = "popin 75%" })
hl.animation({ leaf = "fadeIn",        enabled = true,  speed = 4.5,  bezier = "punkSnap" })
hl.animation({ leaf = "fadeOut",       enabled = true,  speed = 3.8,  bezier = "punkSlam" })
hl.animation({ leaf = "fade",          enabled = true,  speed = 6,    bezier = "quick" })
hl.animation({ leaf = "layers",        enabled = true,  speed = 7,    bezier = "punkSnap" })
hl.animation({ leaf = "layersIn",      enabled = true,  speed = 7.5,  spring = "aeroSpring", style = "fade" })
hl.animation({ leaf = "layersOut",     enabled = true,  speed = 3.5,  bezier = "punkSlam",       style = "fade" })
hl.animation({ leaf = "fadeLayersIn",  enabled = true,  speed = 4.2,  bezier = "punkSnap" })
hl.animation({ leaf = "fadeLayersOut", enabled = true,  speed = 3.5,  bezier = "punkSlam" })
hl.animation({ leaf = "workspaces",    enabled = true,  speed = 4.6,  bezier = "aeroSwing",  style = "slidevert" })
hl.animation({ leaf = "workspacesIn",  enabled = true,  speed = 3.6,  spring = "aeroSpring", style = "fade" })
hl.animation({ leaf = "workspacesOut", enabled = true,  speed = 3.6,  bezier = "punkSlam",       style = "fade" })
hl.animation({ leaf = "zoomFactor",    enabled = true,  speed = 9,    bezier = "punkKick" })

