-- See https://wiki.hypr.land/Configuring/Basics/Window-Rules/
-- and https://wiki.hypr.land/Configuring/Basics/Workspace-Rules/

-- Example window rules that are useful

local suppressMaximizeRule = hl.window_rule({
    -- Ignore maximize requests from all apps. You'll probably like this.
    name  = "suppress-maximize-events",
    match = { class = ".*" },

    suppress_event = "maximize",
})
-- suppressMaximizeRule:set_enabled(false)

hl.window_rule({
    -- Fix some dragging issues with XWayland
    name  = "fix-xwayland-drags",
    match = {
        class      = "^$",
        title      = "^$",
        xwayland   = true,
        float      = true,
        fullscreen = false,
        pin        = false,
    },

    no_focus = true,
})

hl.layer_rule({
  name = "noctalia",
  match = {
    namespace = "^noctalia-(bar-.+|notification|dock|panel|attached-panel|osd|window-switcher)$",
  },
  no_anim = true,
  ignore_alpha = 0.5,
  blur = true,
  blur_popups = true,
  xray = true, -- deja que el blur "vea" lo que hay detrás del panel, más vidrio real
})

-- Ventanas flotantes chicas (diálogos, popups): rounding un poco mayor
-- para que combinen con el resto. El blur ya las cubre automáticamente
-- vía el bloque global de "decoration" — no existe un campo "blur" a
-- nivel de window_rule en Hyprland (eso sí existe en layer_rule).
hl.window_rule({
    name  = "glass-floating-dialogs",
    match = { float = true },

    rounding = 16,
})

