-- For Noctalia Color templates
--
-- OJO: noctalia.lua NO es config, lo GENERA Noctalia (dice "Generated by
-- Noctalia" en la primera línea). Con require pelado, si el archivo no está
-- Hyprland aborta la carga de toda la config y te deja medio escritorio con
-- un error en la última línea. Como es opcional de verdad, que falte solo
-- significa que no se aplica la paleta de colores.
--
-- Y no solo el require: también la llamada. apply_theme() hace un hl.config()
-- con los colores que generó Noctalia, y si Hyprland no acepta alguno (nueva
-- nueva, clave cambiada, color con sintaxis no soportada) el error salta DENTRO
-- de la llamada y se reporta en esta línea. Un archivo generado y cosmético no
-- puede tirar abajo la config.
local _ok, _noctalia = pcall(require, "noctalia")
if not _ok then
  print("[hyprland] no encontré el módulo 'noctalia' (lo genera Noctalia); sigo sin su paleta")
elseif type(_noctalia) ~= "table" or type(_noctalia.apply_theme) ~= "function" then
  print("[hyprland] el módulo 'noctalia' no trae apply_theme; lo salto")
else
  local _applied, _why = pcall(_noctalia.apply_theme)
  if not _applied then
    print("[hyprland] apply_theme() falló: " .. tostring(_why))
    print("[hyprland] el resto de la config está bien; solo falta la paleta de Noctalia")
  end
end